    addFilter().role("resource1-filter1-role").impl("resource1-filter1-impl").param().name("resource1-filter1-param1-name").value("resource1-filter1-param1-value").up().param().name("resource1-filter1-param2-name").value("resource1-filter1-param2-value").up().up().addFilter().name("resource1-filter2-name").role("resource1-filter2-role").impl("resource1-filter2-impl").up().up();
