    assertThat(doc, hasXPath("/gateway/resource[1]/filter[1]/param[1]/value", is("resource1-filter1-param1-value")));
    assertThat(doc, hasXPath("/gateway/resource[1]/filter[1]/param[2]/name", is("resource1-filter1-param2-name")));
