@Test
public void testListener() throws Exception {
    // Setup the base GatewayConfig mock
    gc = EasyMock.createNiceMock(GatewayConfig.class);
    EasyMock.expect(gc.getRemoteRegistryConfigurationNames()).andReturn(Collections.singletonList(configMonitorName)).anyTimes();
    final String registryConfig = GatewayConfig.REMOTE_CONFIG_REGISTRY_TYPE + "=" + ZooKeeperClientService.TYPE + ";" + GatewayConfig.REMOTE_CONFIG_REGISTRY_ADDRESS + "=" + zkNodes.getConnectString();
    EasyMock.expect(gc.getRemoteRegistryConfiguration(configMonitorName)).andReturn(registryConfig).anyTimes();
    EasyMock.expect(gc.getRemoteConfigurationMonitorClientName()).andReturn(configMonitorName).anyTimes();
    EasyMock.expect(gc.isRemoteAliasServiceEnabled()).andReturn(true).anyTimes();
    EasyMock.replay(gc);
    // Mock Alias Service
    final DefaultAliasService defaultAlias = EasyMock.createNiceMock(DefaultAliasService.class);
    // Captures for validating the alias creation for a generated topology
    final Capture<String> capturedCluster = EasyMock.newCapture();
    final Capture<String> capturedAlias = EasyMock.newCapture();
    final Capture<String> capturedPwd = EasyMock.newCapture();
    defaultAlias.addAliasForCluster(capture(capturedCluster), capture(capturedAlias), capture(capturedPwd));
    EasyMock.expectLastCall().anyTimes();
    /* defaultAlias.getAliasesForCluster() never returns null */
    EasyMock.expect(defaultAlias.getAliasesForCluster(expectedClusterName)).andReturn(new ArrayList<>()).anyTimes();
    EasyMock.expect(defaultAlias.getAliasesForCluster(expectedClusterNameDev)).andReturn(new ArrayList<>()).anyTimes();
    EasyMock.expect(defaultAlias.getPasswordFromAliasForCluster(expectedClusterName, preferRemoteAlias)).andReturn("thisiswrong".toCharArray()).anyTimes();
    EasyMock.replay(defaultAlias);
    final DefaultMasterService ms = EasyMock.createNiceMock(DefaultMasterService.class);
    EasyMock.expect(ms.getMasterSecret()).andReturn("knox".toCharArray()).anyTimes();
    EasyMock.replay(ms);
    final RemoteAliasService zkAlias = new RemoteAliasService();
    final RemoteConfigurationRegistryClientService clientService = (new ZooKeeperClientServiceProvider()).newInstance();
    clientService.setAliasService(zkAlias);
    clientService.init(gc, Collections.emptyMap());
    /* init */
    zkAlias.setLocalAliasService(defaultAlias);
    zkAlias.setRegistryClientService(clientService);
    zkAlias.setMasterService(ms);
    zkAlias.init(gc, Collections.emptyMap());
    zkAlias.start();
    /* GET Aliases */
    List<String> aliases = zkAlias.getAliasesForCluster(expectedClusterName);
    List<String> aliasesDev = zkAlias.getAliasesForCluster(expectedClusterNameDev);
    /* no alias added so ist should be empty, except the one in ZK  */
    Assert.assertEquals(aliases.size(), 1);
    Assert.assertEquals(aliasesDev.size(), 0);
    /* Create an alias in Zookeeper externally */
    client.create().withMode(CreateMode.PERSISTENT).forPath(RemoteAliasService.PATH_KNOX_ALIAS_STORE_TOPOLOGY + RemoteAliasService.PATH_SEPARATOR + expectedClusterName + RemoteAliasService.PATH_SEPARATOR + expectedAlias, zkAlias.encrypt(expectedPassword).getBytes());
    /* Create an alias in Zookeeper externally */
    client.create().withMode(CreateMode.PERSISTENT).forPath(RemoteAliasService.PATH_KNOX_ALIAS_STORE_TOPOLOGY + RemoteAliasService.PATH_SEPARATOR + expectedClusterNameDev + RemoteAliasService.PATH_SEPARATOR + expectedAliasDev, zkAlias.encrypt(expectedPasswordDev).getBytes());
    /* Try */
    aliases = zkAlias.getAliasesForCluster(expectedClusterName);
    aliasesDev = zkAlias.getAliasesForCluster(expectedClusterNameDev);
    Assert.assertTrue(aliases.contains(expectedAlias), "Expected alias 'knox.test.alias' not found ");
    Assert.assertTrue(aliasesDev.contains(expectedAliasDev), "Expected alias 'knox.test.alias.dev' not found ");
    final char[] result = zkAlias.getPasswordFromAliasForCluster(expectedClusterName, expectedAlias);
    final char[] result1 = zkAlias.getPasswordFromAliasForCluster(expectedClusterNameDev, expectedAliasDev);
    /* make sure the externally added passwords match */
    Assert.assertEquals(expectedPassword, new String(result));
    Assert.assertEquals(expectedPasswordDev, new String(result1));
    /* test that remote alias service prefers remote over local */
    final char[] prefAliasResult = zkAlias.getPasswordFromAliasForCluster(expectedClusterName, preferRemoteAlias);
    Assert.assertEquals(preferRemoteAliasClearPassword, new String(prefAliasResult));
    zkAlias.stop();
}

@Test
public void testAliasForCluster() throws Exception {
    final String expectedClusterName = "sandbox";
    final String expectedAlias = "knox.test.alias";
    final String expectedPassword = "dummyPassword";
    final String expectedClusterNameDev = "development";
    final String expectedAliasDev = "knox.test.alias.dev";
    final String expectedPasswordDev = "otherDummyPassword";
    // Mock Alias Service
    final DefaultAliasService defaultAlias = EasyMock.createNiceMock(DefaultAliasService.class);
    // Captures for validating the alias creation for a generated topology
    final Capture<String> capturedCluster = EasyMock.newCapture();
    final Capture<String> capturedAlias = EasyMock.newCapture();
    final Capture<String> capturedPwd = EasyMock.newCapture();
    defaultAlias.addAliasForCluster(capture(capturedCluster), capture(capturedAlias), capture(capturedPwd));
    EasyMock.expectLastCall().anyTimes();
    /* defaultAlias.getAliasesForCluster() never returns null */
    EasyMock.expect(defaultAlias.getAliasesForCluster(expectedClusterName)).andReturn(new ArrayList<>()).anyTimes();
    EasyMock.expect(defaultAlias.getAliasesForCluster(expectedClusterNameDev)).andReturn(new ArrayList<>()).anyTimes();
    EasyMock.replay(defaultAlias);
    final DefaultMasterService ms = EasyMock.createNiceMock(DefaultMasterService.class);
    EasyMock.expect(ms.getMasterSecret()).andReturn("knox".toCharArray()).anyTimes();
    EasyMock.replay(ms);
    final RemoteAliasService zkAlias = new RemoteAliasService();
    RemoteConfigurationRegistryClientService clientService = (new ZooKeeperClientServiceProvider()).newInstance();
    clientService.setAliasService(zkAlias);
    clientService.init(gc, Collections.emptyMap());
    /* init */
    zkAlias.setLocalAliasService(defaultAlias);
    zkAlias.setRegistryClientService(clientService);
    zkAlias.setMasterService(ms);
    zkAlias.init(gc, Collections.emptyMap());
    zkAlias.start();
    /* Put */
    zkAlias.addAliasForCluster(expectedClusterName, expectedAlias, expectedPassword);
    zkAlias.addAliasForCluster(expectedClusterNameDev, expectedAliasDev, expectedPasswordDev);
    /* GET all Aliases */
    List<String> aliases = zkAlias.getAliasesForCluster(expectedClusterName);
    List<String> aliasesDev = zkAlias.getAliasesForCluster(expectedClusterNameDev);
    Assert.assertEquals(aliases.size(), 1);
    Assert.assertEquals(aliasesDev.size(), 1);
    Assert.assertTrue(aliases.contains(expectedAlias), "Expected alias 'knox.test.alias' not found ");
    Assert.assertTrue(aliasesDev.contains(expectedAliasDev), "Expected alias 'knox.test.alias.dev' not found ");
    final char[] result = zkAlias.getPasswordFromAliasForCluster(expectedClusterName, expectedAlias);
    final char[] result1 = zkAlias.getPasswordFromAliasForCluster(expectedClusterNameDev, expectedAliasDev);
    Assert.assertEquals(expectedPassword, new String(result));
    Assert.assertEquals(expectedPasswordDev, new String(result1));
    /* Remove */
    zkAlias.removeAliasForCluster(expectedClusterNameDev, expectedAliasDev);
    /* Make sure expectedAliasDev is removed*/
    aliases = zkAlias.getAliasesForCluster(expectedClusterName);
    aliasesDev = zkAlias.getAliasesForCluster(expectedClusterNameDev);
    Assert.assertEquals(aliasesDev.size(), 0);
    Assert.assertFalse(aliasesDev.contains(expectedAliasDev), "Expected alias 'knox.test.alias.dev' to be removed but found.");
    Assert.assertEquals(aliases.size(), 1);
    Assert.assertTrue(aliases.contains(expectedAlias), "Expected alias 'knox.test.alias' not found ");
    /* Test auto-generate password for alias */
    final String testAutoGeneratedpasswordAlias = "knox.test.alias.auto";
    final char[] autoGeneratedPassword = zkAlias.getPasswordFromAliasForCluster(expectedClusterName, testAutoGeneratedpasswordAlias, true);
    aliases = zkAlias.getAliasesForCluster(expectedClusterName);
    Assert.assertNotNull(autoGeneratedPassword);
    Assert.assertEquals(aliases.size(), 2);
    Assert.assertTrue(aliases.contains(testAutoGeneratedpasswordAlias), "Expected alias 'knox.test.alias' not found ");
}

