    assertThat(output.getParameterName(), is(""));
    assertThat(output.getOriginalPattern(), is("{X"));
    assertThat(output.getEffectivePattern(), is("{X"));
    input = "X}";
    output = Parser.parseTemplateToken(builder, input, "~");
    assertThat(output.getParameterName(), is(""));
    assertThat(output.getOriginalPattern(), is("X}"));
    assertThat(output.getEffectivePattern(), is("X}"));
    input = "X";
    output = Parser.parseTemplateToken(builder, input, "~");
    assertThat(output.getParameterName(), is(""));
    assertThat(output.getOriginalPattern(), is("X"));
    assertThat(output.getEffectivePattern(), is("X"));
